import sys

def longest_non_decreasing_subsequence_length(s):
    if not s:
        return 0

    n = len(s)
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if s[i] >= s[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

